using PA.Tickets.Application.Foundations;
using PA.Tickets.Application.Reporting;
namespace PA.Tickets.Infrastructure.Reporting;
public sealed class DashboardService(IKpiService kpis,IReportingQueryService reports,IAuthorizationService authorization,TimeProvider clock):IDashboardService
{
 static readonly KpiPeriodKind[] Periods=[KpiPeriodKind.Day,KpiPeriodKind.Week,KpiPeriodKind.Month,KpiPeriodKind.Custom];
 static readonly string[] Filters=["period","clientId","departmentId","teamId","serviceId","categoryId","subCategoryId","requestTypeId","ticketType","priorityId","requesterId","assigneeId"];
 static readonly IReadOnlyCollection<DashboardDefinition> Defs=Build();
 static IReadOnlyCollection<DashboardDefinition> Build()=>[
  Def("operations","Operations","High-level operational overview",[K("openBacklog","Open Backlog","OPEN_BACKLOG","count"),K("slaCompliance","SLA Compliance","SLA_COMPLIANCE","percentage"),K("averageTicketAge","Average Ticket Age","AVERAGE_TICKET_AGE","minutes"),K("reopenRate","Reopen Rate","REOPEN_RATE","percentage"),R("ticketVolume","Ticket Volume",DashboardWidgetType.Trend,"ticket-volume"),R("statusDistribution","Status Distribution",DashboardWidgetType.Distribution,"ticket-status-summary"),R("departmentWorkload","Department Workload",DashboardWidgetType.Workload,"department-workload"),R("priorityDistribution","Priority Distribution",DashboardWidgetType.Distribution,"ticket-volume"),R("agingDistribution","Aging Distribution",DashboardWidgetType.Aging,"ticket-aging-buckets")]),
  Def("sla","SLA","SLA performance overview",[K("slaCompliance","SLA Compliance","SLA_COMPLIANCE","percentage"),K("firstResponseTime","First Response Time","FIRST_RESPONSE_TIME","minutes"),K("resolutionTime","Resolution Time","RESOLUTION_TIME","minutes"),R("responsePerformance","SLA Response Performance",DashboardWidgetType.Table,"sla-response-performance"),R("resolutionPerformance","SLA Resolution Performance",DashboardWidgetType.Table,"sla-resolution-performance"),R("breachedTickets","Breached Tickets",DashboardWidgetType.Table,"sla-breached-tickets")]),
  Def("workload","Workload","Assignment and ageing overview",[K("openBacklog","Open Backlog","OPEN_BACKLOG","count"),K("averageTicketAge","Average Ticket Age","AVERAGE_TICKET_AGE","minutes"),R("departmentWorkload","Department Workload",DashboardWidgetType.Workload,"department-workload"),R("teamWorkload","Team Workload",DashboardWidgetType.Workload,"team-workload"),R("assigneeWorkload","Assignee Workload",DashboardWidgetType.Workload,"assignee-workload"),R("agingDistribution","Aging Distribution",DashboardWidgetType.Aging,"ticket-aging-buckets"),R("ticketTypeDistribution","Ticket Type Distribution",DashboardWidgetType.Distribution,"ticket-type-summary")])];
 static DashboardDefinition Def(string c,string n,string d,IReadOnlyCollection<DashboardWidgetDefinition> w)=>new(c,n,d,1,true,Periods,Filters,w,"TICKET_READ");
 static DashboardWidgetDefinition K(string c,string t,string source,string unit)=>new(c,t,DashboardWidgetType.Kpi,source,unit);
 static DashboardWidgetDefinition R(string c,string t,DashboardWidgetType type,string source)=>new(c,t,type,source);
 public IReadOnlyCollection<DashboardDefinition> Catalogue()=>Defs;
 public DashboardDefinition GetDefinition(string code)=>Defs.FirstOrDefault(x=>x.Code.Equals(code,StringComparison.OrdinalIgnoreCase))??throw new KeyNotFoundException("The requested dashboard was not found.");
 public async Task<DashboardResponse> QueryAsync(string code,DashboardQueryRequest request,long actor,string? correlationId,CancellationToken ct){var d=GetDefinition(code);await authorization.EnsurePermissionAsync(actor,d.Permission,null,ct);var ds=request.Scope??new();var scope=ToKpiScope(ds);var widgets=new List<DashboardWidget>();var first=code.ToLowerInvariant() switch {"operations"=>await AddKpi("OPEN_BACKLOG",scope,request,actor,widgets,ct),"sla"=>await AddKpi("SLA_COMPLIANCE",scope,request,actor,widgets,ct),"workload"=>await AddKpi("OPEN_BACKLOG",scope,request,actor,widgets,ct),_=>throw new KeyNotFoundException("The requested dashboard was not found.")};var filter=ToReportFilter(request,ds);switch(code.ToLowerInvariant()){case "operations":await AddKpi("SLA_COMPLIANCE",scope,request,actor,widgets,ct);await AddKpi("AVERAGE_TICKET_AGE",scope,request,actor,widgets,ct);await AddKpi("REOPEN_RATE",scope,request,actor,widgets,ct);await AddReport("ticket-volume","ticketVolume","Ticket Volume",DashboardWidgetType.Trend,filter,actor,widgets,ct);await AddReport("ticket-status-summary","statusDistribution","Status Distribution",DashboardWidgetType.Distribution,filter,actor,widgets,ct);await AddReport("department-workload","departmentWorkload","Department Workload",DashboardWidgetType.Workload,filter,actor,widgets,ct);await AddReport("ticket-volume","priorityDistribution","Priority Distribution",DashboardWidgetType.Distribution,filter with { Sort = "priority" },actor,widgets,ct);await AddReport("ticket-aging-buckets","agingDistribution","Aging Distribution",DashboardWidgetType.Aging,filter,actor,widgets,ct);break;case "sla":await AddKpi("FIRST_RESPONSE_TIME",scope,request,actor,widgets,ct);await AddKpi("RESOLUTION_TIME",scope,request,actor,widgets,ct);await AddReport("sla-response-performance","responsePerformance","SLA Response Performance",DashboardWidgetType.Table,filter,actor,widgets,ct);await AddReport("sla-resolution-performance","resolutionPerformance","SLA Resolution Performance",DashboardWidgetType.Table,filter,actor,widgets,ct);await AddReport("sla-breached-tickets","breachedTickets","Breached Tickets",DashboardWidgetType.Table,filter,actor,widgets,ct);break;default:await AddKpi("AVERAGE_TICKET_AGE",scope,request,actor,widgets,ct);await AddReport("department-workload","departmentWorkload","Department Workload",DashboardWidgetType.Workload,filter,actor,widgets,ct);await AddReport("team-workload","teamWorkload","Team Workload",DashboardWidgetType.Workload,filter,actor,widgets,ct);await AddReport("assignee-workload","assigneeWorkload","Assignee Workload",DashboardWidgetType.Workload,filter,actor,widgets,ct);await AddReport("ticket-aging-buckets","agingDistribution","Aging Distribution",DashboardWidgetType.Aging,filter,actor,widgets,ct);await AddReport("ticket-type-summary","ticketTypeDistribution","Ticket Type Distribution",DashboardWidgetType.Distribution,filter,actor,widgets,ct);break;}return new DashboardResponse(d.Code,d.Name,clock.GetUtcNow(),new DashboardPeriod(first.MeasurementPeriodStart,first.MeasurementPeriodEnd,request.Period.Kind),request,widgets);}
 async Task<KpiResult> AddKpi(string code,KpiScope scope,DashboardQueryRequest request,long actor,List<DashboardWidget> widgets,CancellationToken ct){var result=await kpis.CalculateAsync(code,new KpiCalculationRequest(request.Period,scope),actor,null,ct);widgets.Add(new DashboardWidget(code,kpis.GetDefinition(code).Name,DashboardWidgetType.Kpi,result.Unit,result,result.Status));return result;}
 async Task AddReport(string code,string widget,string title,DashboardWidgetType type,ReportQueryRequest filter,long actor,List<DashboardWidget> widgets,CancellationToken ct){var result=await reports.QueryAsync(code,filter,actor,null,ct);widgets.Add(new DashboardWidget(widget,title,type,null,result));}
 static KpiScope ToKpiScope(DashboardScope s)=>new(s.ClientId,s.DepartmentId,s.TeamId,s.ServiceId,s.CategoryId,s.SubCategoryId,s.RequestTypeId,s.TicketType,s.PriorityId,s.RequesterId,s.AssigneeId);
 static ReportQueryRequest ToReportFilter(DashboardQueryRequest request,DashboardScope s){var from=request.Period.Kind==KpiPeriodKind.Custom?request.Period.From:request.Period.Date;var to=request.Period.Kind==KpiPeriodKind.Custom?request.Period.To:request.Period.Kind switch{KpiPeriodKind.Day=>request.Period.Date?.AddDays(1),KpiPeriodKind.Week=>request.Period.Date?.AddDays(7),KpiPeriodKind.Month=>request.Period.Date?.AddMonths(1),_=>request.Period.Date};return new ReportQueryRequest(CreatedFrom:from,CreatedTo:to,DepartmentId:s.DepartmentId,TeamId:s.TeamId,ClientId:s.ClientId,ServiceId:s.ServiceId,CategoryId:s.CategoryId,SubCategoryId:s.SubCategoryId,RequestTypeId:s.RequestTypeId,TicketType:s.TicketType is int t?(PA.Tickets.Domain.Tickets.TicketType)t:null,PriorityId:s.PriorityId,RequesterId:s.RequesterId,AssigneeId:s.AssigneeId);}
}

